import {e,icon,link,button,title,panel,table,info,empty} from './ui.js?v=20260919-residents';
import {services,categories,stages,ticketForUnit} from './resident-data.js?v=20260919-residents';
import {technicians} from './data.js?v=20260919-residents';
const categoryIcons=['air','bolt','tap','drop','door','grid'];
const drawings={air:'<path d="M3 8h13a3 3 0 1 0-3-3M3 12h16a3 3 0 1 1-3 3M3 16h7a3 3 0 1 1-3 3"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',tap:'<path d="M3 12h15v5h3v-8h-8V5M8 5h10M5 12v5H2v-5M18 21v-1"/>',drop:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/><path d="M9 16a3 3 0 0 0 3 3"/>',camera:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="m8 6 2-3h4l2 3"/><circle cx="12" cy="13" r="4"/>'};
export const residentIcon=name=>drawings[name]?`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawings[name]}</svg>`:icon(name);
export const timeLabel=value=>new Intl.DateTimeFormat('ar-SA',{calendar:'gregory',numberingSystem:'latn',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value));
export const statusBadge=t=>`<span class="rs-status rs-stage-${t.stage}">${stages[t.stage]}</span>`;
const priority=t=>`<span class="rs-priority ${t.priority==='HIGH'?'urgent':''}">${t.priority==='HIGH'?'عاجلة':'عادية'}</span>`;
export function residentTimeline(t){return `<ol class="rs-timeline" aria-label="مراحل الطلب">${stages.map((s,i)=>`<li class="${i<t.stage?'done':i===t.stage?'current':'pending'}" ${i===t.stage?'aria-current="step"':''}><span class="rs-step-dot">${i<=t.stage?icon('check'):i+1}</span><div><strong>${s}</strong>${i===t.stage?'<small>الحالة الحالية</small>':''}${t.history.find(h=>h.stage===i)?`<time>${e(timeLabel(t.history.find(h=>h.stage===i).at))}</time>`:''}</div></li>`).join('')}</ol>`;}
const residentBack=(base,text='العودة للخدمات')=>link(base,icon('chevron')+text,'rs-back');
export function renderResident(data,path,q,tickets,persistent=true){
  const [, ,unitId,view,ticketId]=path.split('/'),unit=data.units.find(u=>u.id===unitId),base='/service/'+unitId;
  const header=`<header class="rs-header"><div class="rs-brand"><span class="brand-mark">${icon('building')}</span><div><strong>نواة</strong><small>خدمات السكان</small></div></div>${unit?`<span class="rs-unit-pill" dir="ltr">${e(unit.id)}</span>`:''}</header>`;
  let content='';
  if(!unit)content=`<section class="rs-card rs-message">${icon('door')}<h1>رابط الوحدة غير صحيح</h1><p>امسح رمز QR الموجود داخل شقتك للوصول إلى خدمات وحدتك.</p></section>`;
  else if(!view){
    const mine=tickets.filter(t=>t.unitId===unit.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,5);
    content=`<section class="rs-welcome"><span class="rs-eyebrow">خدمات السكان</span><h1>أهلاً بك</h1><div class="rs-address"><span>${icon('building')} المبنى <b dir="ltr">${e(unit.buildingId)}</b></span><span>${icon('door')} الوحدة <b>${unit.number}</b></span></div><h2>كيف يمكننا خدمتك؟</h2></section><div class="rs-services">${Object.entries(services).map(([key,s])=>link(base+'/request?service='+key,`<span class="rs-service-icon">${icon(s.icon)}</span><strong>${s.label}</strong>${icon('left')}`,'rs-service '+(key==='maintenance'?'featured':''))).join('')}</div>${mine.length?`<section class="rs-recent"><h2>طلبات هذه الوحدة</h2>${mine.map(t=>link(base+'/track/'+t.id,`<div><strong>${e(t.category)}</strong><small dir="ltr">${t.id}</small></div><div>${statusBadge(t)}${icon('chevron')}</div>`,'rs-request-row')).join('')}</section>`:''}`;
  }else if(view==='request' && Object.hasOwn(services,q.get('service'))){
    const service=q.get('service');
    content=residentBack(base)+`<h1 class="rs-page-title">${services[service].label}</h1><form id="resident-request-form" class="rs-form" data-unit="${unit.id}" data-service="${service}">${service==='maintenance'?`<fieldset><legend>ما نوع المشكلة؟</legend><div class="rs-categories">${categories.map((c,i)=>`<label class="rs-choice"><input type="radio" name="category" value="${c}" required><span>${residentIcon(categoryIcons[i])}<strong>${c}</strong></span></label>`).join('')}</div></fieldset>`:''}<div class="rs-field"><label for="resident-description">وصف المشكلة</label><textarea id="resident-description" name="description" rows="4" required minlength="5" maxlength="1000" placeholder="اكتب وصفاً مختصراً للمشكلة..."></textarea></div><div class="rs-field"><label for="resident-photo">إرفاق صورة <small>اختياري</small></label><div class="rs-upload"><input id="resident-photo" type="file" accept="image/jpeg,image/png,image/webp" aria-describedby="photo-help"><label for="resident-photo">${residentIcon('camera')}<span>اضغط لإضافة صورة</span></label><small id="photo-help">JPG، PNG أو WebP · حتى 8 ميجابايت</small></div><div id="resident-photo-preview" aria-live="polite"></div></div><fieldset><legend>هل المشكلة عاجلة؟</legend><div class="rs-priorities"><label class="rs-choice"><input name="priority" type="radio" value="NORMAL" checked><span>${icon('clock')}عادية</span></label><label class="rs-choice"><input name="priority" type="radio" value="HIGH"><span>${icon('alert')}عاجلة</span></label></div></fieldset><p id="resident-error" class="form-error" role="alert"></p><button class="rs-primary" type="submit">إرسال الطلب ${icon('left')}</button></form>`;
  }else if(['success','track'].includes(view)){
    const t=ticketForUnit(tickets,ticketId,unit.id);
    if(!t)content=residentBack(base)+`<section class="rs-card rs-message"><h1>الطلب غير موجود</h1><p>لا يوجد هذا الطلب ضمن طلبات الوحدة في هذا المتصفح.</p></section>`;
    else if(view==='success')content=`<section class="rs-card rs-success"><div class="rs-success-icon">${icon('check')}</div><h1>تم استلام طلبك بنجاح</h1><span class="rs-muted">رقم الطلب</span><strong class="rs-ticket-number" dir="ltr">${t.id}</strong>${statusBadge(t)}<p>سيقوم ${t.service==='maintenance'?'فريق الصيانة':'فريق خدمات السكان'} بمراجعة الطلب والتواصل معك عند الحاجة.</p>${link(base+'/track/'+t.id,'متابعة حالة الطلب '+icon('left'),'rs-primary')}${residentBack(base)}</section>`;
    else content=residentBack(base)+`<h1 class="rs-page-title">متابعة حالة الطلب</h1><section class="rs-card"><div class="rs-ticket-top"><strong dir="ltr">${t.id}</strong>${priority(t)}</div><h2>${e(t.category)}</h2><p class="rs-muted">الوحدة <b dir="ltr">${unit.id}</b></p>${residentTimeline(t)}</section><section class="rs-card rs-summary"><h2>وصف المشكلة</h2><p class="rs-description">${e(t.description)}</p>${t.image?`<img class="rs-photo" src="${t.image}" alt="صورة المشكلة المرفقة بالطلب">`:''}</section>`;
  }else content=residentBack(base)+`<section class="rs-card"><h1>الصفحة غير موجودة</h1></section>`;
  return `<div class="resident-shell">${header}<main id="main" class="rs-main" tabindex="-1">${content}${!persistent?'<p class="rs-storage-note">الحفظ في المتصفح غير متاح؛ سيبقى طلبك خلال هذه الجلسة فقط.</p>':''}</main></div>`;
}
export function renderResidentAdmin(data,path,q,tickets){
  const id=path.split('/')[2];
  if(id){
    const t=tickets.find(t=>t.id===id);if(!t)return empty('الطلب غير موجود','اختر طلباً من قائمة طلبات السكان.');
    const unit=data.units.find(u=>u.id===t.unitId),actions=[];
    if(t.stage===0)actions.push(button('بدء المراجعة','resident-review','btn',`data-id="${t.id}"`));
    if(t.stage<=1)actions.push(button(icon('users')+' تعيين فني','resident-assign','btn primary',`data-id="${t.id}"`));
    if(t.stage===2)actions.push(button(icon('play')+' بدء العمل','resident-start','btn primary',`data-id="${t.id}"`));
    if(t.stage===3)actions.push(button(icon('check')+' تم الإصلاح','resident-repair','btn primary',`data-id="${t.id}"`));
    if(t.stage===4)actions.push(button(icon('check')+' إغلاق الطلب','resident-close','btn primary',`data-id="${t.id}"`));
    return link('/resident-requests',icon('chevron')+' طلبات السكان','back-link')+title('خدمات السكان',t.id,`${services[t.service].label} · الوحدة ${t.unitId}`,actions.join(''))+`<div class="two-col equal">${panel('تفاصيل الطلب',info([['رقم الطلب',`<b dir="ltr">${t.id}</b>`],['المبنى',e(unit.buildingId)],['الوحدة',e(unit.number)],['نوع الخدمة',services[t.service].label],['نوع المشكلة',e(t.category)],['وقت الطلب',timeLabel(t.createdAt)],['الأولوية',priority(t)],['الحالة',statusBadge(t)],['الفني المسؤول',e(technicians.find(x=>x.id===t.technicianId)?.name||'لم يتم التعيين')]])+`<div class="rs-admin-description"><h3>وصف المشكلة</h3><p class="rs-description">${e(t.description)}</p><h3>الصورة</h3>${t.image?`<img class="rs-photo" src="${t.image}" alt="صورة المشكلة المرفقة بالطلب">`:'<p class="muted">لا توجد صورة مرفقة.</p>'}</div>`)}${panel('متابعة التنفيذ',residentTimeline(t)+(t.stage===5?'<div class="confirmation">تم إغلاق الطلب.</div>':''))}</div>`;
  }
  const today=new Date().toDateString(),counts=[tickets.filter(t=>t.stage===0).length,tickets.filter(t=>t.priority==='HIGH'&&t.stage<5).length,tickets.filter(t=>t.stage===3).length,tickets.filter(t=>t.history.some(h=>h.stage===4&&new Date(h.at).toDateString()===today)).length];
  const filtered=tickets.filter(t=>(!q.get('status')||q.get('status')==='ALL'||String(t.stage)===q.get('status'))&&(!q.get('priority')||q.get('priority')==='ALL'||t.priority===q.get('priority'))&&(!q.get('search')||(t.id+' '+t.unitId+' '+t.description+' '+t.category).toLowerCase().includes(q.get('search').toLowerCase()))).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  return title('خدمات السكان','طلبات السكان','طلبات الوحدات من رابط QR، في مكان واحد.',button(icon('door')+' تجربة خدمات السكان / QR','resident-qr','btn primary','data-id="A02-105"'))+`<div class="rs-admin-stats">${['طلبات جديدة','طلبات عاجلة','قيد التنفيذ','تمت اليوم'].map((label,i)=>`<div class="panel rs-stat"><span>${label}</span><strong>${counts[i]}</strong>${icon(['file-plus','alert','wrench','check'][i])}</div>`).join('')}</div><div class="toolbar rs-toolbar"><div class="search-field">${icon('search')}<input data-search="search" value="${e(q.get('search')||'')}" placeholder="ابحث بالطلب أو الوحدة..." aria-label="البحث في طلبات السكان"></div><label>الحالة <select data-filter="status">${[['ALL','جميع الحالات'],...stages.map((s,i)=>[String(i),s])].map(([v,l])=>`<option value="${v}" ${q.get('status')===v?'selected':''}>${l}</option>`).join('')}</select></label><label>الأولوية <select data-filter="priority">${[['ALL','كل الأولويات'],['HIGH','عاجلة'],['NORMAL','عادية']].map(([v,l])=>`<option value="${v}" ${q.get('priority')===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${panel('قائمة الطلبات',filtered.length?table(['رقم الطلب','المبنى','الوحدة','نوع الخدمة','وصف مختصر','الأولوية','وقت الطلب','الحالة',''],filtered.map(t=>`<tr><td>${link('/resident-requests/'+t.id,`<b dir="ltr">${t.id}</b>`)}</td><td>${e(t.unitId.split('-')[0])}</td><td>${e(t.unitId.split('-')[1])}</td><td>${services[t.service].label}<small class="rs-table-sub">${e(t.category)}</small></td><td><span class="rs-table-description" title="${e(t.description)}">${e(t.description)}</span></td><td>${priority(t)}</td><td>${timeLabel(t.createdAt)}</td><td>${statusBadge(t)}</td><td>${link('/resident-requests/'+t.id,'فتح الطلب','btn btn-sm')}</td></tr>`)):empty('لا توجد طلبات مطابقة','جرّب تغيير البحث أو التصفية.'))}<p class="small muted">الطلبات محفوظة محلياً في هذا المتصفح لأغراض العرض التجريبي.</p>`;
}
